+test("RF-006: descuento global en porcentaje sobre el total, IVA incluido sobre el total descontado", () => {
+  const items = [
+    { cantidad: 2, precioUnitarioCentavos: 5000 },
+    { cantidad: 1, precioUnitarioCentavos: 1050 },
+  ];
+  // 11050 - 10 % (1105) = 9945; IVA = round(9945 * 0,13) = 1293; neto = 8652
+  assert.deepEqual(calcularFactura(items, { descuentoGlobal: 10 }), {
+    totalCentavos: 9945, ivaCentavos: 1293, netoCentavos: 8652, descuentoCentavos: 1105,
+  });
+  // sin descuento (omitido o 0) el resultado no cambia
+  assert.deepEqual(calcularFactura(items, {}), calcularFactura(items));
+  assert.deepEqual(calcularFactura(items, { descuentoGlobal: 0 }), calcularFactura(items));
+  // 100 % deja el total en 0
+  assert.equal(calcularFactura(items, { descuentoGlobal: 100 }).totalCentavos, 0);
+});
+
+test("RF-006: el descuento se redondea al centavo", () => {
+  // 1001 * 12,5 % = 125,125 -> 125
+  const r = calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1001 }], { descuentoGlobal: 12.5 });
+  assert.equal(r.descuentoCentavos, 125);
+  assert.equal(r.totalCentavos, 876);
+  assert.ok(Number.isInteger(r.ivaCentavos) && Number.isInteger(r.netoCentavos));
+});
+
+test("RF-006: un descuento global fuera de 0–100 o no numérico se rechaza", () => {
+  const items = [{ cantidad: 1, precioUnitarioCentavos: 1000 }];
+  for (const d of [-1, 100.01, NaN, Infinity, "10", null]) {
+    assert.throws(() => calcularFactura(items, { descuentoGlobal: d }), RangeError, String(d));
+  }
+});
